from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Low-volatility tilting is a strategy that assumes stocks with lower volatility tend to outperform."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        symbol_volatility: dict[str, float] = {}
        for symbol in view.symbols:
            if symbol not in history["symbol"].to_list():
                continue
            prices = [float(v) for v in history.filter(pl.col("symbol") == symbol)[
                "adj_close"
            ].drop_nulls().to_list()]
            if len(prices) < self._window:
                continue

            volatility = ((pl.Series(prices).std()) / (prices[-1] - prices[0])) * 100
            symbol_volatility[symbol] = float(volatility)

        sorted_symbols = [
            s for _, s in sorted(symbol_volatility.items(), key=lambda item: item[1])
        ]
        top_symbols = sorted_symbols[:5]
        if not top_symbols:
            return Signal(information_available_at=stamp, weights={})
        weight = 1.0 / len(top_symbols)
        return Signal(
            information_available_at=stamp, weights={s: weight for s in top_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
